import{_ as e,o,c as s,a6 as i}from"./chunks/framework.DNkVJs23.js";const m=JSON.parse('{"title":"Perguntas frequentes","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/pt-br/faq/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/pt-br/faq/"}],["meta",{"property":"og:title","content":"Perguntas frequentes | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"Dados de Monster Hunter e busca de conjuntos para Wilds, Rise com Sunbreak e World com Iceborne."}]]},"headers":[],"relativePath":"pt-br/faq/index.md","filePath":"pt-br/faq/index.md"}'),n={name:"pt-br/faq/index.md"};function t(r,a,p,d,c,l){return o(),s("div",null,[...a[0]||(a[0]=[i('<h1 id="perguntas-frequentes" tabindex="-1">Perguntas frequentes <a class="header-anchor" href="#perguntas-frequentes" aria-label="Permalink to &quot;Perguntas frequentes&quot;">​</a></h1><h2 id="quais-jogos-sao-compativeis" tabindex="-1">Quais jogos são compatíveis? <a class="header-anchor" href="#quais-jogos-sao-compativeis" aria-label="Permalink to &quot;Quais jogos são compatíveis?&quot;">​</a></h2><p>Wilds, Rise com Sunbreak e World com Iceborne. Os dados e as mecânicas ficam separados por jogo; a seleção é feita na tela inicial.</p><h2 id="onde-posso-baixar-o-app" tabindex="-1">Onde posso baixar o app? <a class="header-anchor" href="#onde-posso-baixar-o-app" aria-label="Permalink to &quot;Onde posso baixar o app?&quot;">​</a></h2><p>Android está disponível no <a href="https://play.google.com/store/apps/details?id=com.eurekaffeine.mhd" target="_blank" rel="noreferrer">Google Play</a> e HarmonyOS na <a href="https://appgallery.huawei.com/app/detail?id=com.eurekaffeine.monsterhunterdex&amp;channelId=SHARE&amp;source=appshare" target="_blank" rel="noreferrer">AppGallery</a>. A versão para iOS está em preparação. Consulte os <a href="./../#download">downloads</a>; a disponibilidade varia conforme a região e o dispositivo.</p><h2 id="o-app-funciona-offline" tabindex="-1">O app funciona offline? <a class="header-anchor" href="#o-app-funciona-offline" aria-label="Permalink to &quot;O app funciona offline?&quot;">​</a></h2><p>Os dados acompanham o app. Consultas, buscas, favoritos e busca de armaduras são executados localmente. Links externos e atualizações precisam de conexão.</p><h2 id="como-funciona-a-busca-de-conjuntos" tabindex="-1">Como funciona a busca de conjuntos? <a class="header-anchor" href="#como-funciona-a-busca-de-conjuntos" aria-label="Permalink to &quot;Como funciona a busca de conjuntos?&quot;">​</a></h2><p>Defina habilidades e níveis, fixe ou exclua equipamentos e limite as decorações ao seu inventário. Rise também aceita talismãs e armaduras aumentadas que você possui. Os resultados dependem dos dados e critérios; não é uma calculadora de dano.</p><h2 id="quais-idiomas-estao-disponiveis" tabindex="-1">Quais idiomas estão disponíveis? <a class="header-anchor" href="#quais-idiomas-estao-disponiveis" aria-label="Permalink to &quot;Quais idiomas estão disponíveis?&quot;">​</a></h2><p>O app oferece 14 idiomas. Alguns textos de jogo podem continuar em inglês. Quando falta um texto em espanhol latino-americano, o app procura primeiro o espanhol da Espanha e depois o inglês.</p><p>English · 日本語 · 简体中文 · 繁體中文 · Français · Deutsch · Italiano · 한국어 · Español (España) · Español (Latinoamérica) · Português (Brasil) · Polski · Русский · العربية</p><h2 id="e-um-aplicativo-oficial" tabindex="-1">É um aplicativo oficial? <a class="header-anchor" href="#e-um-aplicativo-oficial" aria-label="Permalink to &quot;É um aplicativo oficial?&quot;">​</a></h2><p>Não. É um app independente feito por fãs, sem vínculo ou aprovação da CAPCOM. As imagens e os dados de Monster Hunter pertencem à CAPCOM Co., Ltd.</p>',14)])])}const f=e(n,[["render",t]]);export{m as __pageData,f as default};
